function crimeRate(a){
  if(a.athens){ const s=ATHENS_DEPTS.reduce((x,d)=>x+DEPT[d][1],0); return {r:s/STATS["Athens"][1]*1000, scope:"όλος ο Δήμος Αθηναίων"}; }
  const d=deptOf(a); if(!d) return null;
  const pop = UNIT[a.name] ? UNIT[a.name][2] : (STATS[a.mid]&&STATS[a.mid][1]);
  if(!pop) return null;
  return {r:DEPT[d][1]/pop*1000, scope:null};
}
