// ----- Θεσσαλονίκη: κατηγορίες από άρθρα (όπως στην Αθήνα) -----
{
  const FT="Foithtips, «Οδηγός φοιτητούπολης: Θεσσαλονίκη» (2012)", EN="Έθνος, «Θεσσαλονίκη: Στο κόκκινο η εγκληματικότητα» (4/2/2020)",
        PX="Parallaxi, «Τα πιο επικίνδυνα σημεία στη Θεσσαλονίκη» (2018)", MK="ΜτΚ, «Οι ζώνες του εγκλήματος στη Θεσσαλονίκη» (2009)";
  const WEST=`${FT}: η δυτική Θεσσαλονίκη (Μενεμένη, Νεάπολη, Εύοσμος, Κορδελιό) αναφέρεται στις περιοχές που καλό είναι να αποφύγει ένας φοιτητής, κυρίως λόγω δύσκολης συγκοινωνίας προς ΑΠΘ και ΠΑ.ΜΑΚ. ${EN}: κλοπές, διαρρήξεις και διακίνηση ναρκωτικών στη δυτική Θεσσαλονίκη, με λίγη αστυνόμευση.`;
  const FAR="Εκτιμώμενος χρόνος με ΜΜΜ ως την Πλ. Αριστοτέλους 60′ ή περισσότερο (δεν προέρχεται από άρθρο).";
  const TC={
    "Κέντρο Θεσσαλονίκης":["ok",`${FT}: «η πιο εύκολη λύση» για φοιτητές (Καμάρα, Ροτόντα, Αγ. Δημητρίου). Προσοχή: ${EN} και ${PX} αναφέρουν διακίνηση ναρκωτικών και κλοπές γύρω από Καμάρα–Ροτόντα, κυρίως βράδυ.`],
    "Τούμπα":["ok",`${FT}: προτείνεται (Άνω–Κάτω Τούμπα, 40 Εκκλησιές).`],
    "Χαριλάου":["ok",`${FT}: προτείνεται.`],
    "Ανάληψη":["ok",`${FT}: προτείνεται (25ης Μαρτίου, Ιπποκράτειο).`],
    "Τριανδρία":["ok",`${FT}: «πολύ ήσυχη συνοικία» με καλά σπίτια και σχετικά καλά ενοίκια.`],
    "Ξηροκρήνη":["avoid",`${EN}: σχεδόν καθημερινές συμπλοκές στην Πλ. Αντιγονιδών και στον νέο σιδηροδρομικό σταθμό. ${PX}: πορνεία και «σκοτεινή ζώνη» σε Γιαννιτσών, Ξυλάδικα και κάτω από τις γραμμές στον Μύλο.`],
    "Δενδροπόταμος":["avoid",`${EN}: αναφέρεται για διακίνηση ναρκωτικών. ${MK}: πρώτη στη λίστα της ΕΛ.ΑΣ. για διακίνηση ναρκωτικών.`],
    "Σταυρούπολη":["avoid",`${EN}: η περιοχή γύρω από το Ψυχιατρικό Νοσοκομείο περιγράφεται ως «σούπερ μάρκετ» εξαρτησιογόνων ουσιών. Το ίδιο σημείο αναφέρει και η ${MK}.`],
    "Εύοσμος":["avoid",WEST], "Ελευθέριο–Κορδελιό":["avoid",WEST], "Μενεμένη":["avoid",WEST], "Νεάπολη":["avoid",WEST],
    "Χορτιάτης":["far",FAR], "Περαία":["far",FAR], "Νέα Μηχανιώνα":["far",FAR], "Επανομή":["far",FAR]
  };
  Object.values(SPLIT).forEach(list=>list.forEach(e=>{ const t=TC[e[0]]; if(t){ e[3]=t[0]; e[4]=t[1]; } }));
  ["T:Delta","T:Chalkidona","T:Lagkadas"].forEach(k=>{ MUNI[k]=["far",FAR]; });
}
const SPLIT_NAMES = new Set(Object.values(SPLIT).flat().map(s=>s[0]));

// Χρόνος με αυτοκίνητο: OSRM όπου υπάρχει, αλλιώς εκτίμηση από την απόσταση
function carOf(a){
  if(a.mid==="Aegina") return null;
  const ferry = a.mid==="Salamina";
  const m = a.city==="athens" && OSRM_TIMES && OSRM_TIMES.times[a.okey];
  if(m){ const off=m[0]+(ferry?25:0); return {off:Math.max(1,Math.round(off)), peak:r5(off*1.7), km:Math.round(m[1]), ferry, osrm:true}; }
  const pt = (!a.athens && TOWN_PT[a.mid] && !UNIT[a.name] && !SPLIT_NAMES.has(a.name)) ? TOWN_PT[a.mid] : a.pt;
  const d = hav(pt, CITIES[a.city||city].center) * 1.35;
  const v = Math.min(45, 16 + 1.4*d);
  let off = 6 + d/v*60, peak = off*1.7;
  if(ferry){ off += 25; peak += 30; }
  return {off:r5(off), peak:r5(peak), km:Math.round(d), ferry};
}

