function pin(lat, lon, path, color, tip, big){
  return L.marker([lat,lon], {icon: L.divIcon({className:"pin"+(big?" big":""), iconSize: big?[34,34]:[24,24], iconAnchor: big?[17,17]:[12,12],
    html:`<span style="background:${color}"><svg viewBox="0 0 24 24"><path d="${path}"/></svg></span>`})}).bindTooltip(tip, {direction:"top", offset:[0,-10]});
}

function buildAll(){
  [L_areas,L_lbl,L_metro,L_walk,L_hosp,L_uni,L_air,L_poi].forEach(l=>l.clearLayers());
  areas = []; state.sel = null; state.cmp = []; state.filter = null;
  AREAS.features.forEach(f=>{
    const p=f.properties; let a;
    if(p.split){ const s=SPLIT[p.parent].find(x=>x[0]===p.key); a={name:s[0], cat:s[3], note:s[4], muni:p.pn, mid:p.parent, athens:p.parent==="Athens"}; }
    else { const [cat,note,cat2] = MUNI[p.key] || ["none"]; a={name:p.n, cat, cat2, note, muni:p.n, mid:p.key}; }
    a.pt = p.lp; a.okey = p.key; a.city = p.city;
    const i = areas.length;
    a.layer = L.geoJSON(f).on("click", ev => { L.DomEvent.stopPropagation(ev); if(window.__pick){ window.__pick(ev.latlng); return; } state.sel = state.sel===i ? null : i; paint(); }).addTo(L_areas);
    a.layer.bindTooltip(a.name, {sticky:true, direction:"top", opacity:.95});
    a.lbl = L.marker([p.lp[1], p.lp[0]], {interactive:false, keyboard:false, icon: L.divIcon({className:"mlbl", html:`<span>${a.name}</span>`, iconSize:null})});
    areas.push(a);
  });

  // Μετρό και κύκλοι 500 m, και για τις δύο πόλεις
  const seen = new Set();
  [...METRO, ...METRO_T].forEach(([col,name,st])=>{
    const okey = (METRO_T.some(m=>m[1]===name&&m[0]===col) ? "T:" : "") + name, og = window.OSM_LINES && OSM_LINES[okey];
    L.polyline(og ? og : st.map(([lo,la])=>[la,lo]), {color:col, weight:4, opacity:.8, pane:"lines", interactive:false}).addTo(L_metro);
    st.forEach(([lo,la,sn])=>{
      L.circleMarker([la,lo], {radius:3.5, color:col, weight:2, fillColor:"#fff", fillOpacity:1, pane:"lines"}).bindTooltip(sn?`${name}: ${sn}`:name).addTo(L_metro);
      const k=lo.toFixed(3)+","+la.toFixed(3); if(seen.has(k)) return; seen.add(k);
      L.circle([la,lo], {radius:500, color:tok("walk"), weight:1, fillColor:tok("walk"), fillOpacity:.14, pane:"walk", interactive:false}).addTo(L_walk);
    });
  });
  if(window.OSM_LINES && OSM_LINES.tram) L.polyline(OSM_LINES.tram, {color:tok("tram"), weight:3, dashArray:"7 5", pane:"lines", interactive:false}).addTo(L_metro);
  else Object.values(TS).forEach(seg=>L.polyline(seg.map(([,la,lo])=>[la,lo]), {color:tok("tram"), weight:3, dashArray:"7 5", pane:"lines", interactive:false}).addTo(L_metro));
  const ts=new Set(); Object.values(TS).flat().forEach(([n,la,lo])=>{ if(ts.has(n)) return; ts.add(n);
    L.circleMarker([la,lo], {radius:2.8, color:tok("tram"), weight:1.5, fillColor:"#fff", fillOpacity:1, pane:"lines"}).bindTooltip("Τραμ: "+n).addTo(L_metro); });

  // Σημεία ενδιαφέροντος
  [...HOSP, ...HOSP_T].forEach(([n,lo,la,,src])=>pin(la,lo,ICON_CROSS,tok("hosp"),`Νοσοκομείο: ${n} · ${src}`).addTo(L_hosp));
  if(typeof HOSP_X!=="undefined") HOSP_X.forEach(([n,lo,la])=>L.circleMarker([la,lo],{radius:5,color:"#fff",weight:1.5,fillColor:tok("hosp"),fillOpacity:.9}).bindTooltip(`${n} · θέση: OpenStreetMap`).addTo(L_hosp));
  [...UNIS, ...UNIS_T].forEach(([n,lo,la,,src])=>pin(la,lo,ICON_CAP,tok("uni"),`${n} · ${src}`).addTo(L_uni));
  [...AIR, ...AIR_T].forEach(([n,lo,la,lvl,txt])=>pin(la,lo,ICON_AIR, lvl===2?tok("hosp"):lvl===1?tok("air"):tok("ok"), `Σταθμός ${n}: ${txt}`).addTo(L_air));
  [["Αεροδρόμιο Ελ. Βενιζέλος",23.9445,37.9369,"plane","#0072bc"],["Λιμάνι Πειραιά",23.626,37.936,"ship","#0b5a7a"], ...POIS_T]
    .forEach(([n,lo,la,ic,col])=>pin(la,lo,ICONS[ic],col,n,true).addTo(L_poi));

  // Ονόματα πόλεων όταν βλέπεις όλη την Ελλάδα
  Object.entries(CITIES).forEach(([k,c])=>L.marker([c.center[1],c.center[0]], {keyboard:true, title:c.name,
    icon:L.divIcon({className:"citylbl", html:`<span>${c.name}</span>`, iconSize:null})}).on("click",()=>setCity(k)).addTo(L_city));

  const dl = document.getElementById("qlist"); dl.innerHTML = "";
  [...new Set(areas.map(a=>a.name))].sort((a,b)=>a.localeCompare(b,"el")).forEach(n=>{const o=document.createElement("option"); o.value=n; dl.appendChild(o);});
}
const L_city = L.layerGroup();
function updateCityUI(){
  document.getElementById("mkey").innerHTML = city==="athens"
    ? `<div><span class="ln" style="background:#00943e"></span><b>Γραμμή 1</b><span class="rt">Πειραιάς – Κηφισιά</span></div>
       <div><span class="ln" style="background:#e2231a"></span><b>Γραμμή 2</b><span class="rt">Ανθούπολη – Ελληνικό</span></div>
       <div><span class="ln" style="background:#1c3f94"></span><b>Γραμμή 3</b><span class="rt">Δημ. Θέατρο – Αεροδρόμιο</span></div>
       <div><span class="ln tr"></span><b>Τραμ</b><span class="rt">Σύνταγμα – Πειραιάς / Βούλα</span></div>`
    : `<div><span class="ln" style="background:#d7262f"></span><b>Γραμμή 1</b><span class="rt">Ν. Σιδ. Σταθμός – Νέα Ελβετία</span></div>
       <div><span class="ln" style="background:#1d6fb8"></span><b>Γραμμή 2</b><span class="rt">επέκταση Καλαμαριάς: 25ης Μαρτίου – Μίκρα</span></div>`;
  document.getElementById("h1").textContent = `Πού (δεν) θα μείνεις ${C().in}`;
  document.getElementById("intro").textContent = C().intro;
  document.getElementById("center-name").textContent = C().centerName;
  ["all","mid","center"].forEach((v,j)=>document.getElementById("tab-"+v).textContent = C().tabs[j]);
  ["athens","thess"].forEach(c=>document.getElementById("city-"+c).setAttribute("aria-pressed", c===city));
  document.title = `Πού θα μείνεις · ${C().name}`;
  try{ history.replaceState(null,"", city==="thess" ? "#thessaloniki" : "#athens"); }catch(e){}
}
// Η πόλη αλλάζει μόνη της ανάλογα με το πού κοιτάς στον χάρτη
function cityFromView(){
  const c=map.getCenter(); let best=null, bd=1e9;
  Object.entries(CITIES).forEach(([k,v])=>{ const d=hav([c.lng,c.lat], v.center); if(d<bd){bd=d; best=k;} });
  if(map.getZoom()>=8.5 && bd<120 && best!==city){ city=best; updateCityUI(); legend(); finderResult(); }
  if(map.getZoom()<8.5) L_city.addTo(map); else map.removeLayer(L_city);
  map.getContainer().classList.toggle("far", map.getZoom()<8.5);
}
map.on("moveend", cityFromView);

// ===== Χρώματα και ετικέτες =====
const BAND_FN = { time:a=>bandOf(timeOf(a)), car:a=>{const c=carOf(a); return c?bandOf(c.peak):null}, crime:a=>cbandOf(a), rent:a=>rbandOf(a) };
function styleFor(a, i, fa){
  const c = catOf(a), two = a.cat2 && !custom[a.name];
  let fill, border = tok("edge"), w = 1, dash = null, b = null;
  if(state.mode==="cats"){ fill = tok(c); if(two){ border = tok(a.cat2); w = 3; dash = "6 4"; } }
  else { b = BAND_FN[state.mode](a); fill = tok(b||"none"); }
  const on = fa ? matches(a) : !state.filter ? true
           : state.mode==="cats" ? (state.filter===c || (two && state.filter===a.cat2)) : state.filter===b;
  const empty = (state.mode==="cats" && c==="none") || (state.mode!=="cats" && !b);
  if(state.sel===i){ border = tok("sel"); w = 3.5; dash = null; }
  return { fillColor: fill, fillOpacity: !on ? .06 : empty ? .18 : .55, color: border, weight: w, opacity: on ? .9 : .25, dashArray: dash };
}
function labels(){
  const z = map.getZoom();
  areas.forEach(a=>{
    const c = catOf(a);
    const show = a.athens ? z>=14 : SPLIT_NAMES.has(a.name) ? z>=12.5 : (state.mode==="cats" && c!=="none") ? z>=10 : z>=11;
    if(show) a.lbl.addTo(L_lbl); else L_lbl.removeLayer(a.lbl);
  });
}
map.on("zoomend", labels);
map.on("click", ()=>{ if(state.sel!=null){ state.sel=null; paint(); } });

function paint(){
  const fa = finderActive();
  areas.forEach((a,i)=>a.layer.setStyle(styleFor(a,i,fa)));
  if(state.sel!=null) areas[state.sel].layer.bringToFront();
  labels(); legend(); info(); finderResult(); renderCmp();
}

function legend(){
  const counts={}; areas.filter(a=>a.city===city).forEach(a=>{const c=catOf(a); counts[c]=(counts[c]||0)+1; if(a.cat2&&!custom[a.name]) counts[a.cat2]=(counts[a.cat2]||0)+1});
  const ul=document.getElementById("legend"); ul.innerHTML="";
  document.getElementById("legend-h").textContent = state.mode==="time" ? "Ως το κέντρο με ΜΜΜ (εκτίμηση)" : state.mode==="car" ? "Ως το κέντρο με αυτοκίνητο, ώρα αιχμής (εκτίμηση)" : state.mode==="crime" ? "Κλοπές-διαρρήξεις 2025 ανά 1.000 κατοίκους" : state.mode==="rent" ? "Μέσο ενοίκιο 2026 (ζητούμενο)" : state.mode==="score" ? "Βαθμολογία περιοχής (0–100)" : "Κατηγορίες";
  if(state.mode==="time" || state.mode==="car" || state.mode==="crime" || state.mode==="rent" || state.mode==="score"){
    const fn = state.mode==="time" ? (a=>bandOf(timeOf(a))) : state.mode==="car" ? (a=>{const c=carOf(a); return c?bandOf(c.peak):null}) : state.mode==="rent" ? rbandOf : state.mode==="score" ? sbandOf : cbandOf, B = state.mode==="score" ? SBANDS : (state.mode==="time"||state.mode==="car") ? BANDS : state.mode==="rent" ? RBANDS : CBANDS;
    const tc={}; areas.filter(a=>a.city===city).forEach(a=>{const b=fn(a); tc[b]=(tc[b]||0)+1});
    Object.entries(B).forEach(([k,c])=>{
      const li=document.createElement("li"), b=document.createElement("button");
      b.setAttribute("aria-pressed",state.filter===k);
      b.innerHTML=`<span class="sw" style="background:var(--${k})"></span><span><b>${c.name}</b><small>${c.ex}</small></span><span class="cnt">${tc[k]||0}</span>`;
      b.onclick=()=>{state.filter=state.filter===k?null:k; paint()};
      li.appendChild(b); ul.appendChild(li);
    });
    return;
  }
  Object.entries(CATS).forEach(([k,c])=>{
    const li=document.createElement("li"), b=document.createElement("button");
    b.setAttribute("aria-pressed",state.filter===k);
    b.innerHTML=`<span class="sw" style="background:var(--${k})"></span><span><b>${c.name}</b><small>${c.ex}</small></span><span class="cnt">${counts[k]||0}</span>`;
    b.onclick=()=>{state.filter=state.filter===k?null:k; paint()};
    li.appendChild(b); ul.appendChild(li);
  });
}

const nf = new Intl.NumberFormat("el-GR");
function statsFor(a, dl){
  const u = UNIT[a.name], s = STATS[a.mid], g = GREEN[a.mid];
  const scope = u ? u[0] : (a.muni!==a.name ? "Στοιχεία για όλο τον δήμο: "+a.muni : "");
  const area = u?u[1]:s&&s[0], pop = u?u[2]:s&&s[1];
  const row=(k,v,n,tg)=>{ if(state.mode!=="cats" && state.mode!=="score" && !(tg||"").split(",").includes(state.mode)) return ""; n=(n||""); const un=updNote(k); n = n ? n+un : un.replace(/^ · /,""); return `<dt>${T(k)}</dt><dd>${v}${n?`<small>${n}</small>`:""}</dd>`; };
  let h="";
  h+=row("Έκταση", area?(APPROX_AREA.has(a.mid)&&!u?"≈ ":"")+nf.format(area)+" km²":"—", (APPROX_AREA.has(a.mid)&&!u?"Υπολογισμένη από τα όρια του χάρτη. ":"")+scope);
  h+=row("Πληθυσμός", pop?nf.format(pop)+" κάτοικοι":"—", pop&&area?`${nf.format(Math.round(pop/area))} κάτ./km² · ΕΛΣΤΑΤ, απογραφή 2021`:"", "crime");
  const uo = !a.athens && !u && UNITS_OF[a.mid];
  if(uo) h+=row("Δημοτικές ενότητες", uo.length, uo.map(([n,p])=>`${n} ${nf.format(p)}`).join(" · "));
  const tm=timeOf(a);
  h+=row("Με ΜΜΜ", tm?`~${tm}′ ως ${destLabel()}`:"—", tm?ptSrc(a):"", "time");
  const co=carOf(a);
  h+=row("Με αυτοκίνητο", co?`~${co.off}′ χωρίς κίνηση · ~${co.peak}′ σε ώρα αιχμής`:"—", co?`Περίπου ${co.km} km οδικώς. ${co.osrm?"Οδική διαδρομή από OSRM/OpenStreetMap. Ο χρόνος αιχμής είναι εκτίμηση (×1,7)":"Εκτίμηση από την απόσταση, όχι μέτρηση κίνησης"}${co.ferry?". Περιλαμβάνει το πορθμείο Περάματος–Σαλαμίνας":""}.`:"Νησί: χρειάζεται πλοίο.", "car");
  const rn=rentOf(a);
  h+=row("Ενοίκιο", rn?`${nf.format(rn[0])} €/m²`:"—", rn?`${rn[1]}. Μέση ζητούμενη τιμή.`:"Δεν βρέθηκε δημοσιευμένη μέση τιμή για αυτή την περιοχή.", "rent");
  const dn=deptOf(a);
  if(dn){
    const [ap,kl,ox,li]=DEPT[dn], cr=crimeRate(a);
    const rate = cr ? `${nf.format(Math.round(cr.r*10)/10)} κλοπές-διαρρήξεις ανά 1.000 κατ.${cr.scope?" ("+cr.scope+")":""}` : "";
    h+=row("Έγκλημα 2025", `${nf.format(kl)} κλοπές-διαρρήξεις · ${nf.format(li)} ληστείες`,
      `${nf.format(ox)} κλοπές οχημάτων · ${nf.format(ap)} απάτες. Α.Τ. ${dn}${a.athens?" (περιοχή ευθύνης κατά προσέγγιση)":""}. ${rate}`, "crime");
  } else {
    h+=row("Έγκλημα 2025", a.city==="thess"?"—":`~${nf.format(ATTICA_AVG.r)} κλοπές-διαρρήξεις ανά 1.000 κατ. (μέσος όρος Αττικής)`, a.city==="thess"?"Δεν υπάρχουν στοιχεία ανά τμήμα για αυτή την περιοχή.":`Δεν υπάρχουν στοιχεία για το αστυνομικό τμήμα αυτής της περιοχής, γι' αυτό μπαίνει ο μέσος όρος της Αττικής. ${ATTICA_AVG.src}.`, "crime");
  }
  h+=row("Πράσινο", g?nf.format(g[0])+" m² ανά κάτοικο":"—", g?g[1]+". Ο ΠΟΥ προτείνει τουλάχιστον 9 m².":"Δεν υπάρχουν δημοσιευμένα στοιχεία για αυτόν τον δήμο.");
  dl.innerHTML=h;
}
function info(){
  const el=document.getElementById("info");
  if(state.sel==null){el.innerHTML=`<h2>Περιοχή</h2><p class="empty">Πάτα μια περιοχή στον χάρτη.</p>`;return}
  const a=areas[state.sel], c=catOf(a), mine=custom[a.name];
  const sub = "";
  let why = mine ? "Δική σου κατάταξη." + (a.cat!=="none"?` Η πηγή τη βάζει στο «${CATS[a.cat].short}».`:"")
                 : (a.note || (isDerived(a) ? "Κατάταξη από τα στοιχεία, όχι από άρθρο: "+derivedCat(a)[1]+". Μπορείς να την αλλάξεις εσύ παρακάτω." : "Δεν την αναφέρει καμία πηγή. Διάλεξε εσύ κατηγορία."));
  el.innerHTML=`<h2>Περιοχή</h2><p class="name"></p><dl class="stats"></dl><p class="why"></p><div class="chips"></div>`;
  statsFor(a, el.querySelector(".stats"));
  el.querySelector(".name").textContent=a.name;
  el.querySelector(".why").textContent=sub+why;
  const chips=el.querySelector(".chips");
  if(state.mode!=="cats"){ el.querySelector(".why").remove(); chips.remove(); }
  else Object.entries(CATS).forEach(([kk,cc])=>{
    const b=document.createElement("button"); b.className="chip"; b.setAttribute("aria-pressed",c===kk || (!!a.cat2 && !custom[a.name] && a.cat2===kk));
    b.innerHTML=`<span class="sw" style="background:var(--${kk})"></span>${cc.short}`;
    b.onclick=()=>{ if(kk===a.cat) delete custom[a.name]; else custom[a.name]=kk; save(); paint() };
    chips.appendChild(b);
  });
  const cb=document.createElement("button"); cb.className="chip cmpbtn";
  const inC = state.cmp.includes(state.sel);
  cb.textContent = inC ? "✓ Στη σύγκριση (αφαίρεση)" : "+ Πρόσθεσε στη σύγκριση";
  cb.onclick=()=>{ const i=state.sel; if(inC) state.cmp=state.cmp.filter(x=>x!==i); else { state.cmp.push(i); if(state.cmp.length>2) state.cmp.shift(); } paint(); if(!inC && state.cmp.length===2) document.getElementById("cmp").scrollIntoView({behavior:"smooth",block:"nearest"}); };
  el.appendChild(cb);
}


// ----- Βρες μου περιοχή -----
const fv = id => document.getElementById(id);
function finderActive(){ return fv("f-time").value||fv("f-car").value||fv("f-crime").value||fv("f-rent").value||fv("f-noavoid").checked||fv("f-nopricey").checked||fv("f-nofar").checked; }
function matches(a){
  const unk = fv("f-unknown").checked;
  const test = (val, max) => max==="" ? true : (val==null ? unk : val <= +max);
  const t=timeOf(a), cr=crimeRate(a), rn=rentOf(a);
  if(!test(t, fv("f-time").value)) return false;
  { const c=carOf(a); if(!test(c&&c.peak, fv("f-car").value)) return false; }
  if(fv("f-crime").value!=="" && !(cr==null ? unk : cr.r < +fv("f-crime").value)) return false;
  if(!test(rn&&rn[0], fv("f-rent").value)) return false;
  const cats = [catOf(a)]; if(a.cat2 && !custom[a.name]) cats.push(a.cat2);
  if(fv("f-noavoid").checked && cats.includes("avoid")) return false;
  if(fv("f-nopricey").checked && cats.includes("pricey")) return false;
  if(fv("f-nofar").checked && cats.includes("far")) return false;
  return true;
}
function finderResult(){
  const box=fv("f-res");
  if(!finderActive()){ box.innerHTML='<span class="empty">Διάλεξε κριτήρια και θα φωτιστούν μόνο οι περιοχές που ταιριάζουν.</span>'; return; }
  const hits = areas.map((a,i)=>[a,i]).filter(([a])=>matches(a)).sort((x,y)=>x[0].name.localeCompare(y[0].name,"el"));
  box.innerHTML = hits.length ? `Ταιριάζουν <b>${hits.length}</b> περιοχές. Πάτα μία για να τη δεις:` : "Καμία περιοχή δεν ταιριάζει. Χαλάρωσε κάποιο κριτήριο.";
  const wrap=document.createElement("div"); wrap.className="hits";
  hits.forEach(([a,i])=>{const b=document.createElement("button"); b.type="button"; b.textContent=a.name; b.onclick=()=>focusArea(i); wrap.appendChild(b);});
  box.appendChild(wrap);
}
["f-time","f-car","f-crime","f-rent","f-noavoid","f-nopricey","f-nofar","f-unknown"].forEach(id=>fv(id).addEventListener("change",()=>{state.filter=null; paint();}));

// ----- Αναζήτηση -----
const norm = s => s.normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase().replace(/[^a-zα-ω0-9 ]/g," ").replace(/\s+/g," ").trim();
{
  const dl=fv("qlist"); [...new Set(areas.map(a=>a.name))].sort((a,b)=>a.localeCompare(b,"el")).forEach(n=>{const o=document.createElement("option"); o.value=n; dl.appendChild(o);});
}
function focusArea(i){
  const a=areas[i], bb=a.el.node().getBBox();
  const pad=Math.max(bb.width,bb.height)*0.9+25;
  const x0=bb.x-pad, x1=bb.x+bb.width+pad, y0=bb.y-pad, y1=bb.y+bb.height+pad;
  const k=Math.max(1,Math.min(12,Math.min(W/(x1-x0),H/(y1-y0))));
  const t=d3.zoomIdentity.translate(W/2,H/2).scale(k).translate(-(x0+x1)/2,-(y0+y1)/2);
  svg.transition().duration(700).call(zoom.transform,t);
  state.sel=i; paint();
  document.querySelector(".mapbox").scrollIntoView({behavior:"smooth",block:"nearest"});
}
function doSearch(){
  const q=norm(fv("q").value); const msg=fv("qmsg");
  if(!q){ msg.textContent=""; return; }
  let i = areas.findIndex(a=>norm(a.name)===q);
  if(i<0) i = areas.findIndex(a=>norm(a.name).includes(q));
  if(i<0) i = areas.findIndex(a=>norm(a.muni).includes(q));
  if(i<0){ msg.textContent="Δεν βρέθηκε. Δοκίμασε άλλο όνομα."; return; }
  msg.textContent=""; focusArea(i);
}
fv("search").addEventListener("submit",e=>{e.preventDefault(); doSearch();});
fv("q").addEventListener("change",doSearch);

// ----- Σύγκριση -----
function cmpRows(a){
  const s=STATS[a.mid], u=UNIT[a.name], pop=u?u[2]:s&&s[1], ar=u?u[1]:s&&s[0];
  const cr=crimeRate(a), dn=deptOf(a), rn=rentOf(a), g=GREEN[a.mid], tm=timeOf(a);
  const cats=[CATS[catOf(a)].short]; if(a.cat2&&!custom[a.name]) cats.push(CATS[a.cat2].short);
  return [
    ["Κατηγορία", cats.join(" + "), null],
    ["Με ΜΜΜ ως το κέντρο", tm?`~${tm}′`:"—", tm??null, "low"],
    ["Με αυτοκίνητο (αιχμή)", carOf(a)?`~${carOf(a).peak}′`:"—", carOf(a)?carOf(a).peak:null, "low"],
    ["Ενοίκιο", rn?`${nf.format(rn[0])} €/m²`:"—", rn?rn[0]:null, "low"],
    ["Κλοπές-διαρρήξεις / 1.000", cr?nf.format(Math.round(cr.r*10)/10)+(cr.scope?" *":""):"—", cr?cr.r:null, "low"],
    ["Ληστείες 2025 (τμήμα)", dn?nf.format(DEPT[dn][3]):"—", dn?DEPT[dn][3]:null, "low"],
    ["Πληθυσμός", pop?nf.format(pop)+(a.athens?" *":""):"—", null],
    ["Πυκνότητα (κάτ./km²)", pop&&ar?nf.format(Math.round(pop/ar))+(a.athens?" *":""):"—", null],
    ["Πράσινο (m²/κάτ.)", g?nf.format(g[0]):"—", g?g[0]:null, "high"]
  ];
}
function renderCmp(){
  const box=fv("cmp");
  state.cmp = state.cmp.filter(i=>areas[i]);
  if(!state.cmp.length){ box.hidden=true; box.innerHTML=""; return; }
  box.hidden=false;
  const A=state.cmp.map(i=>areas[i]), R=A.map(cmpRows);
  let h=`<h2>Σύγκριση</h2><div class="tw"><table><thead><tr><th></th>`;
  A.forEach((a,j)=>{h+=`<th>${a.name}<button class="x" data-j="${j}" aria-label="Αφαίρεση ${a.name}">×</button></th>`;});
  if(A.length<2) h+=`<th style="color:var(--muted);font-size:14px;font-weight:500">Διάλεξε δεύτερη περιοχή στον χάρτη και πάτα «Πρόσθεσε στη σύγκριση»</th>`;
  h+=`</tr></thead><tbody>`;
  R[0].forEach((row,r)=>{
    h+=`<tr><th>${row[0]}</th>`;
    let win=-1;
    if(A.length===2 && row[3] && R[0][r][2]!=null && R[1][r][2]!=null && R[0][r][2]!==R[1][r][2]){
      const v0=R[0][r][2], v1=R[1][r][2]; win = row[3]==="low" ? (v0<v1?0:1) : (v0>v1?0:1);
    }
    R.forEach((rr,j)=>{h+=`<td class="${win===j?"win":""}">${rr[r][1]}</td>`;});
    if(A.length<2) h+=`<td></td>`;
    h+=`</tr>`;
  });
  h+=`</tbody></table></div><p class="note">Με πράσινο η καλύτερη τιμή. * Για γειτονιές της Αθήνας ο πληθυσμός και η εγκληματικότητα ανά κάτοικο αφορούν όλο τον δήμο· οι ληστείες αφορούν το αστυνομικό τμήμα της γειτονιάς.</p>`;
  box.innerHTML=h;
  box.querySelectorAll(".x").forEach(b=>b.onclick=()=>{state.cmp.splice(+b.dataset.j,1); paint();});
}



