function allAreas(){
  return AREAS.features.map(f=>{ const p=f.properties; let a;
    if(p.split){ const s=SPLIT[p.parent].find(x=>x[0]===p.key); a={name:s[0], cat:s[3], note:s[4], muni:p.pn, mid:p.parent, athens:p.parent==="Athens"}; }
    else { const [cat,note,cat2] = MUNI[p.key] || ["none"]; a={name:p.n, cat, cat2, note, muni:p.n, mid:p.key}; }
    a.pt=p.lp; a.okey=p.key; a.city=p.city; return a; });
}

