const CITY_CRIME = { thess:{ src:"ΕΛ.ΑΣ., Γ.Α.Δ. Θεσσαλονίκης, Απολογισμός έργου 2025", pop:1092919, kl:7068, kl24:10688, li:291, ox:1939 } };
const cityOf = a => a.city || "athens";
function exportRows(list){
  return list.map(a=>{
    const s=STATS[a.mid], u=UNIT[a.name], pop=u?u[2]:s&&s[1], ar=u?u[1]:s&&s[0];
    const c=carOf(a), r=rentOf(a), dn=deptOf(a), cr=crimeRate(a), g=GREEN[a.mid], two=a.cat2&&!custom[a.name];
    return { "πόλη": cityOf(a)==="thess"?"Θεσσαλονίκη":"Αθήνα", "περιοχή":a.name, "δήμος":a.muni,
      "κατηγορία":CATS[catOf(a)].short, "κατηγορία_2": two?CATS[a.cat2].short:"", "πηγή_κατηγορίας": custom[a.name]?"δική σου κατάταξη":(a.note||(isDerived(a)?"από τα στοιχεία: "+derivedCat(a)[1]:"")),
      "πληθυσμός_2021":pop||"", "πληθυσμός_αφορά": u?u[0]:(a.muni!==a.name?"όλο τον δήμο":"δήμο"), "έκταση_km2":ar||"",
      "ΜΜΜ_ως_κέντρο_λεπτά":timeOf(a)||"", "ΜΜΜ_πηγή": gtfsOf(a)!=null ? "ΟΑΣΑ GTFS 2016-17" : "εκτίμηση", "αυτοκίνητο_εκτός_αιχμής_λεπτά":c?c.off:"", "αυτοκίνητο_αιχμή_λεπτά":c?c.peak:"", "αυτοκίνητο_πηγή":c?(c.osrm?"OSRM":"εκτίμηση"):"",
      "ενοίκιο_ευρώ_ανά_m2":r?r[0]:"", "ενοίκιο_πηγή":r?r[1]:"",
      "αστυνομικό_τμήμα":dn||"", "κλοπές_διαρρήξεις_2025":dn?DEPT[dn][1]:"", "ληστείες_2025":dn?DEPT[dn][3]:"", "κλοπές_οχημάτων_2025":dn?DEPT[dn][2]:"", "απάτες_2025":dn?DEPT[dn][0]:"",
      "κλοπές_ανά_1000_κατοίκους":cr?Math.round(cr.r*10)/10:"", "κλοπές_ανά_1000_αφορά": cr?(cr.avg?"μέσος όρος Αττικής 2025":cr.nomos?"μέσος όρος Γ.Α.Δ. Θεσσαλονίκης 2025":(cr.scope||"αστυνομικό τμήμα")):"", "πράσινο_m2_ανά_κάτοικο":g?g[0]:"" };
  });
}
function toCSV(rows){
  const cols=Object.keys(rows[0]);
  const cell=v=>{ if(typeof v==="number") v=String(v).replace(".",","); v=String(v??""); return /[;"\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v; };
  return "﻿"+[cols.join(";"), ...rows.map(r=>cols.map(c=>cell(r[c])).join(";"))].join("\r\n");
}
function datasetRows(list){
  const by = k => { const out={}; list.forEach(a=>{ const c=cityOf(a); out[c]=out[c]||[0,0]; out[c][1]++; if(k(a)) out[c][0]++; }); return out; };
  const cov = o => Object.entries(o).map(([c,[n,t]])=>`${c==="thess"?"Θεσ/νίκη":"Αθήνα"} ${n}/${t}`).join(" · ");
  const O='<span class="kind o">επίσημο</span>', E='<span class="kind e">εκτίμηση</span>', A='<span class="kind a">άρθρα / αγγελίες</span>';
  return [
    ["Όρια δήμων","geoBoundaries (CC BY 4.0), απλοποιημένα",cov(by(a=>!SPLIT_NAMES.has(a.name))),O],
    ["Γειτονιές μέσα σε δήμους","Χάραξη από το κέντρο κάθε γειτονιάς (Voronoi)",cov(by(a=>SPLIT_NAMES.has(a.name))),E],
    ["Πληθυσμός","ΕΛΣΤΑΤ, Απογραφή 2021",cov(by(a=>{const s=STATS[a.mid],u=UNIT[a.name]; return u||s;})),O],
    ["Κατηγορίες (αποφυγή, οκ, ακριβή, μακριά)","Oneman, Spitogatos, δικές σου κατατάξεις",cov(by(a=>catOf(a)!=="none")),A],
    ["Χρόνος με ΜΜΜ (Αθήνα, δρομολόγια)","Δρομολόγια ΟΑΣΑ, GTFS Δεκ. 2016 – Ιούν. 2017, με την επέκταση της Γραμμής 3",cov(by(a=>gtfsOf(a)!=null)),O],
    ["Χρόνος με ΜΜΜ (εκτίμηση)","Εκτίμηση από διαδρομές μετρό, τραμ, λεωφορείων: Θεσσαλονίκη και περιοχές εκτός ΟΑΣΑ",cov(by(a=>gtfsOf(a)==null && timeOf(a))),E],
    ["Χρόνος με αυτοκίνητο","OSRM όπου υπάρχει, αλλιώς εκτίμηση από την απόσταση",cov(by(a=>carOf(a))),E],
    ["Εγκληματικότητα ανά τμήμα","ΕΛ.ΑΣ. 2025 ανά αστυνομικό τμήμα (Αθήνα)",cov(by(a=>deptOf(a))),O],
    ["Εγκληματικότητα, μέσος όρος Αττικής","ΕΛ.ΑΣ. 2025: 76 κλοπές-διαρρήξεις ανά 10.000 κατ. (για περιοχές χωρίς στοιχεία τμήματος)",cov(by(a=>a.city!=="thess"&&!deptOf(a))),O],
    ["Εγκληματικότητα νομού Θεσσαλονίκης","ΕΛ.ΑΣ., Γ.Α.Δ. Θεσσαλονίκης, Απολογισμός 2025: 7.068 κλοπές-διαρρήξεις, 291 ληστείες, 1.939 κλοπές οχημάτων","μόνο σύνολο νομού",O],
    ["Ενοίκια (ζητούμενα)","Ελεύθερος Τύπος (Ιαν. 2026), REMAX 2026, E-Real Estates, Indomio (Σεπ. 2026)",cov(by(a=>rentOf(a))),A],
    ["Πράσινο ανά κάτοικο","Διπλωματική ΕΜΠ 2022, ΟΟΣΑ",cov(by(a=>GREEN[a.mid])),A],
    ["Στάσεις τραμ","Wikipedia, List of Athens Tram stops","60 στάσεις",O],
    ["Σταθμοί μετρό Θεσσαλονίκης","Wikipedia, άρθρα σταθμών","18 σταθμοί, Γραμμές 1 και 2",O],["Σταθμοί μετρό Αθήνας","Wikipedia, άρθρα σταθμών","66 σταθμοί, Γραμμές 1–3",O],["Νοσοκομεία, πανεπιστήμια","Wikipedia όπου υπάρχει (401, Αλεξάνδρα, ΚΑΤ, Σισμανόγλειο, ΕΚΠΑ, ΟΠΑ, Χαροκόπειο, Παν. Μακεδονίας)· τα υπόλοιπα κατά προσέγγιση","10 από 37",E],
    ["Ποιότητα αέρα","ΥΠΕΝ, Ετήσια Έκθεση Ατμοσφαιρικής Ρύπανσης 2025","13 σταθμοί Αθήνας, 8 Θεσσαλονίκης",O]
  ];
}
