// ----- Geoagent (δοκιμαστική έκδοση) -----
{
  const btn=document.getElementById("ga-btn"), box=document.getElementById("ga"), msgs=document.getElementById("ga-msgs");
  const say=(txt,who="bot")=>{const d=document.createElement("div"); d.className="m "+who; d.textContent=txt; msgs.appendChild(d); msgs.scrollTop=msgs.scrollHeight;};
  let greeted=false;
  const open=o=>{box.hidden=!o; btn.setAttribute("aria-expanded",o); if(o){ if(!greeted){ say("Γεια! Είμαι ο Geoagent. Γράψε μου το όνομα μιας περιοχής και θα σου τη δείξω στον χάρτη με τα στοιχεία της. Σύντομα θα μπορώ να κάνω πολύ περισσότερα."); greeted=true;} document.getElementById("ga-in").focus(); }};
  btn.onclick=()=>open(box.hidden); document.getElementById("ga-x").onclick=()=>open(false);
  document.getElementById("ga-f").addEventListener("submit",e=>{
    e.preventDefault(); const inp=document.getElementById("ga-in"), q=inp.value.trim(); if(!q) return; say(q,"me"); inp.value="";
    const nq=norm(q); let i=areas.findIndex(a=>norm(a.name)===nq); if(i<0) i=areas.findIndex(a=>nq.includes(norm(a.name))||norm(a.name).includes(nq));
    if(i>=0){ const a=areas[i]; focusArea(i); const t=timeOf(a), r=rentOf(a), c=crimeRate(a);
      say(`${a.name}: ${t?`~${t}′ με ΜΜΜ ως το κέντρο`:"χωρίς εκτίμηση χρόνου"}${r?` · ενοίκιο ~${nf.format(r[0])} €/m²`:""}${c?` · ${nf.format(Math.round(c.r*10)/10)} κλοπές-διαρρήξεις ανά 1.000 κατοίκους`:""}. Τη δείχνω στον χάρτη.`); }
    else say("Δεν βρήκα αυτή την περιοχή. Δοκίμασε ένα όνομα δήμου ή γειτονιάς, π.χ. «Κυψέλη» ή «Μαρούσι».");
  });
}


