const T = s => (LANG==="en" && s!=null && I18N[s]) ? I18N[s] : s;
const GR2L = {"α":"a","β":"v","γ":"g","δ":"d","ε":"e","ζ":"z","η":"i","θ":"th","ι":"i","κ":"k","λ":"l","μ":"m","ν":"n","ξ":"x","ο":"o","π":"p","ρ":"r","σ":"s","ς":"s","τ":"t","υ":"y","φ":"f","χ":"ch","ψ":"ps","ω":"o"};
function translit(s){
  let t = s.normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase();
  t = t.replace(/ου/g,"ou").replace(/αυ/g,"av").replace(/ευ/g,"ev").replace(/γγ/g,"ng").replace(/γκ/g,"gk").replace(/μπ/g,"b").replace(/ντ/g,"nt");
  t = [...t].map(c=>GR2L[c] ?? c).join("");
  return t.replace(/(^|[\s(–-])([a-z])/g,(m,p,c)=>p+c.toUpperCase());
}
const dispName = n => LANG==="en" ? `${translit(n)}` : n;
const STATIC_ORIG = new WeakMap();
function applyStaticLang(){
  document.documentElement.lang = LANG;
  document.querySelectorAll("button, label, h2, option, th, .msg, a, .empty, summary").forEach(el=>{
    el.childNodes.forEach(nd=>{
      if(nd.nodeType!==3) return;
      if(!STATIC_ORIG.has(nd)) STATIC_ORIG.set(nd, nd.textContent);
      const o = STATIC_ORIG.get(nd), core = o.trim();
      if(!core) return;
      nd.textContent = LANG==="en" && I18N[core] ? o.replace(core, I18N[core]) : o;
    });
  });
  const q=document.getElementById("q"); if(q) q.placeholder = LANG==="en" ? "Search an area, e.g. Kypseli" : "Αναζήτηση περιοχής, π.χ. Κυψέλη";
  const lb=document.getElementById("lang-btn"); if(lb) lb.textContent = LANG==="en" ? "ΕΛ" : "EN";
}

