const destActive = a => state.dest && (!a || a.city===state.dest.city);
const destLabel = () => (state.dest && state.dest.city===city) ? `«${state.dest.name}»` : `${LANG==="en"?"":"το "}${T(C().centerName)}`;
{
  const _time = timeOf;
  timeOf = a => {
    if(!destActive(a)) return _time(a);
    if(state.dest.gi!=null){ const g=gtfsOf(a,state.dest.gi); if(g!=null) return g; }
    const d = hav(a.pt, [state.dest.lon, state.dest.lat]);
    return Math.max(5, Math.round((8 + 3*d)/5)*5);          // εκτίμηση: 8′ πρόσβαση + ~20 km/h
  };
  const _car = carOf;
  carOf = function(a){
    if(!destActive(a)) return _car(a);
    if(a.mid==="Aegina") return null;
    const pt = (!a.athens && TOWN_PT[a.mid] && !UNIT[a.name] && !SPLIT_NAMES.has(a.name)) ? TOWN_PT[a.mid] : a.pt;
    const d = hav(pt, [state.dest.lon, state.dest.lat]) * 1.35, v = Math.min(45, 16 + 1.4*d);
    let off = 6 + d/v*60, peak = off*1.7; if(a.mid==="Salamina"){ off+=25; peak+=30; }
    return {off:r5(off), peak:r5(peak), km:Math.round(d), ferry:a.mid==="Salamina"};
  };
}
