// ----- Βαθμολογία 0–100 -----
const WDEF = {time:3, rent:3, crime:3, air:2, green:1};
let W = {...WDEF};
try{ W = {...WDEF, ...JSON.parse(localStorage.getItem("weights")||"{}")}; }catch(e){}
const WLABEL = {time:"Χρόνος ως τον προορισμό", rent:"Ενοίκιο", crime:"Εγκληματικότητα", air:"Αέρας", green:"Πράσινο"};
const AIRV = [...AIR, ...AIR_T].map(([n,lo,la,lvl,txt])=>{
  const no2 = /NO₂ (\d+)/.exec(txt), pm = /PM10 (\d+)/.exec(txt);
  return {lo, la, v: no2 ? +no2[1] : pm ? +pm[1]*1.2 : null};
}).filter(x=>x.v!=null);
function airOf(a){
  let best=null, bd=15;
  AIRV.forEach(s=>{ const d=hav(a.pt,[s.lo,s.la]); if(d<bd){bd=d; best=s;} });
  return best ? best.v : null;
}
const METRIC = { time:a=>timeOf(a)??null, rent:a=>{const r=rentOf(a); return r?r[0]:null}, crime:a=>{const r=crimeRate(a); return r&&!r.nomos&&!r.avg?r.r:null},
                 air:a=>airOf(a), green:a=>{const g=GREEN[a.mid]; return g?g[0]:null} };
const BETTER = {time:-1, rent:-1, crime:-1, air:-1, green:1};
let SC = null;
function computeScores(){
  const res = new Map(), all = allAreas();
  ["athens","thess"].forEach(c=>{
    const list = all.filter(a=>a.city===c), pct = {};
    for(const k in METRIC){
      const vals = list.map(a=>[a,METRIC[k](a)]).filter(x=>x[1]!=null);
      const sorted = [...new Set(vals.map(x=>x[1]))].sort((x,y)=>x-y), m = new Map();
      vals.forEach(([a,v])=>{ const r = sorted.length>1 ? sorted.indexOf(v)/(sorted.length-1) : 0.5; m.set(a, 100*(BETTER[k]<0 ? 1-r : r)); });
      pct[k] = m;
    }
    list.forEach(a=>{
      let s=0, w=0; const parts={};
      for(const k in METRIC){ const v=pct[k].get(a); if(W[k]>0 && v!=null){ s+=W[k]*v; w+=W[k]; parts[k]=Math.round(v); } }
      res.set(a.city+"|"+a.name, Object.keys(parts).length>=2 ? {s:s/w, n:Object.keys(parts).length, parts} : null);
    });
  });
  return res;
}
const scoreOf = a => { if(!SC) SC = computeScores(); return SC.get(a.city+"|"+a.name) || null; };
const SBANDS = { s3:{name:"Πολύ καλή (75–100)", ex:"με βάση τα βάρη σου"}, s2:{name:"Καλή (50–75)", ex:"με βάση τα βάρη σου"},
                 s1:{name:"Μέτρια (25–50)", ex:"με βάση τα βάρη σου"}, s0:{name:"Χαμηλή (0–25)", ex:"με βάση τα βάρη σου"} };
const sbandOf = a => { const s=scoreOf(a); if(!s) return null; return s.s>=75?"s3":s.s>=50?"s2":s.s>=25?"s1":"s0"; };
BAND_FN.score = sbandOf;

function renderWeights(){
  const box=document.getElementById("weights"); if(!box) return;
  box.innerHTML = Object.keys(WDEF).map(k=>`<label class="wt"><span>${T(WLABEL[k])}</span><input type="range" min="0" max="5" step="1" id="w-${k}" value="${W[k]}" aria-label="${T(WLABEL[k])}"><output id="wo-${k}">${W[k]}</output></label>`).join("");
  Object.keys(WDEF).forEach(k=>{
    const el=document.getElementById("w-"+k);
    el.oninput=()=>{ W[k]=+el.value; document.getElementById("wo-"+k).textContent=el.value; try{localStorage.setItem("weights",JSON.stringify(W))}catch(e){} paint(); };
  });
}

