// ----- OpenStreetMap: σχολεία, σούπερ μάρκετ, φαρμακεία, πάρκα -----
const L_osm = L.layerGroup(); let osmOn=false, osmTimer=null; const osmCache=new Map();
const OSM_KIND = { pharmacy:["Φαρμακείο","#2e8b57"], school:["Σχολείο","#d9822b"], supermarket:["Σούπερ μάρκετ","#6a5acd"], park:["Πάρκο","#3f9b3f"] };
function osmMsg(t){ const m=document.getElementById("osm-msg"); if(m){ m.textContent=t||""; m.hidden=!t; } }
function osmDraw(els){
  L_osm.clearLayers();
  els.forEach(e=>{
    const t=e.tags||{}, kind = t.amenity==="pharmacy"?"pharmacy":t.amenity==="school"?"school":t.shop==="supermarket"?"supermarket":t.leisure==="park"?"park":null;
    if(!kind) return; const la=e.lat??e.center?.lat, lo=e.lon??e.center?.lon; if(la==null) return;
    L.circleMarker([la,lo],{radius:kind==="park"?6:4.5, color:"#fff", weight:1.5, fillColor:OSM_KIND[kind][1], fillOpacity:.95})
      .bindTooltip(`${T(OSM_KIND[kind][0])}${t.name?": "+t.name:""}`).addTo(L_osm);
  });
}
function osmLoad(){
  if(!osmOn) return;
  if(map.getZoom()<14){ L_osm.clearLayers(); osmMsg(T("Μεγέθυνε περισσότερο για να δεις σχολεία, σούπερ μάρκετ, φαρμακεία και πάρκα.")); return; }
  const b=map.getBounds(), bb=[b.getSouth(),b.getWest(),b.getNorth(),b.getEast()].map(v=>v.toFixed(3)).join(",");
  if(osmCache.has(bb)){ osmDraw(osmCache.get(bb)); osmMsg(""); return; }
  osmMsg(T("Φόρτωση από το OpenStreetMap…"));
  const q=`[out:json][timeout:25];(node["amenity"="pharmacy"](${bb});nwr["amenity"="school"](${bb});nwr["shop"="supermarket"](${bb});way["leisure"="park"](${bb}););out center 500;`;
  fetch("https://overpass-api.de/api/interpreter",{method:"POST", body:"data="+encodeURIComponent(q), headers:{"Content-Type":"application/x-www-form-urlencoded"}})
    .then(r=>{ if(!r.ok) throw new Error(r.status); return r.json(); })
    .then(d=>{ osmCache.set(bb,d.elements||[]); osmDraw(d.elements||[]); osmMsg(""); })
    .catch(()=>osmMsg(LANG==="en" ? "Could not load OpenStreetMap data here. It works on the published site." : "Δεν φορτώθηκαν τα δεδομένα του OpenStreetMap εδώ. Δουλεύει στο δημοσιευμένο site."));
}
map.on("moveend", ()=>{ clearTimeout(osmTimer); osmTimer=setTimeout(osmLoad, 600); });

// ----- Αναφορά λάθους -----
function reportUI(a){
  const d=document.createElement("details"); d.className="report";
  d.innerHTML=`<summary>${T("Αναφορά λάθους για αυτή την περιοχή")}</summary>
    <label class="rlab">${T("Τι είναι λάθος ή τι λείπει;")}<textarea rows="3"></textarea></label>
    <button type="button" class="chip">${T("Αποστολή αναφοράς")}</button><span class="msg rmsg"></span>`;
  d.querySelector("button").onclick = async ()=>{
    const txt=d.querySelector("textarea").value.trim(), m=d.querySelector(".rmsg");
    if(!txt){ m.textContent = LANG==="en"?"Write what is wrong first.":"Γράψε πρώτα τι είναι λάθος."; return; }
    const title=`Διόρθωση: ${a.name} (${a.city==="thess"?"Θεσσαλονίκη":"Αθήνα"})`;
    const body=`Περιοχή: ${a.name}\nΔήμος: ${a.muni}\nΠόλη: ${a.city==="thess"?"Θεσσαλονίκη":"Αθήνα"}\n\n${txt}`;
    if(REPORT.github){
      const l=document.createElement("a"); l.href=`https://github.com/${REPORT.github}/issues/new?title=${encodeURIComponent(title)}&body=${encodeURIComponent(body)}`;
      l.target="_blank"; l.rel="noopener"; document.body.appendChild(l); l.click(); l.remove();
      m.textContent = LANG==="en"?"A new tab opened to submit the report.":"Άνοιξε νέα καρτέλα για να υποβάλεις την αναφορά.";
    } else if(REPORT.email){
      location.href=`mailto:${REPORT.email}?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(body)}`;
      m.textContent = (LANG==="en"?"If no email app opened, write to ":"Αν δεν άνοιξε το email σου, στείλε στο ")+REPORT.email;
    } else {
      try{ await navigator.clipboard.writeText(title+"\n\n"+body); m.textContent = LANG==="en"?"Copied. No recipient has been set up yet.":"Η αναφορά αντιγράφηκε. Δεν έχει οριστεί ακόμα παραλήπτης."; }
      catch(e){ m.textContent = LANG==="en"?"No recipient has been set up yet.":"Δεν έχει οριστεί ακόμα παραλήπτης αναφορών."; }
    }
  };
  return d;
}

// ----- Επεκτάσεις υπαρχουσών συναρτήσεων -----
{
  const _statsFor = statsFor;
  statsFor = function(a, dl){
    _statsFor(a, dl);
    const sc = scoreOf(a);
    if(sc){
      const p = Object.entries(sc.parts).map(([k,v])=>`${T(WLABEL[k])} ${v}`).join(" · ");
      dl.insertAdjacentHTML("afterbegin", `<dt>${T("Βαθμολογία")}</dt><dd><b class="scorev">${Math.round(sc.s)}</b>/100<small>${p} · ${sc.n}/5 ${LANG==="en"?"criteria":"κριτήρια"}</small></dd>`);
    }
    if(a.city==="thess"){ [...dl.querySelectorAll("dt")].filter(d=>d.textContent===T("Έγκλημα 2025")).forEach(d=>{ d.nextElementSibling&&d.nextElementSibling.remove(); d.remove(); }); }
    if(a.city==="thess" && (state.mode==="crime"||state.mode==="cats"||state.mode==="score")){
      const t=CITY_CRIME.thess;
      dl.insertAdjacentHTML("beforeend", `<dt>${T("Έγκλημα")}</dt><dd>${nf.format(Math.round(t.kl/t.pop*10000)/10)} ${LANG==="en"?"thefts & burglaries per 1,000 (Thessaloniki police average)":"κλοπές-διαρρήξεις ανά 1.000 (μέσος όρος Γ.Α.Δ. Θεσσαλονίκης)"}<small>ΕΛ.ΑΣ., Γ.Α.Δ. Θεσσαλονίκης, Απολογισμός 2025. ${LANG==="en"?"No per-municipality data":"Δεν υπάρχουν στοιχεία ανά δήμο"}.</small></dd>`);
    }
  };
  const _info = info;
  info = function(){
    _info();
    const el=document.getElementById("info");
    const nm=el.querySelector(".name"); if(nm && LANG==="en" && state.sel!=null) nm.textContent = `${translit(areas[state.sel].name)} · ${areas[state.sel].name}`;
    const h=el.querySelector("h2"); if(h) h.textContent=T("Περιοχή");
    const em=el.querySelector(".empty"); if(em) em.textContent=T("Πάτα μια περιοχή στον χάρτη.");
    const cb=el.querySelector(".cmpbtn"); if(cb) cb.textContent=T(cb.textContent);
    if(state.sel!=null){
      el.appendChild(reportUI(areas[state.sel]));
      const x=document.createElement("button"); x.type="button"; x.className="sheet-x"; x.setAttribute("aria-label",T("Κλείσιμο")); x.textContent="×";
      x.onclick=()=>{ state.sel=null; paint(); }; el.prepend(x);
    }
  };
  const _legend = legend;
  legend = function(){
    _legend();
    const h=document.getElementById("legend-h");
    if(state.mode==="time") h.textContent = (LANG==="en"?"To ":"Ως ") + destLabel() + (LANG==="en"?" by public transport (estimate)":" με ΜΜΜ (εκτίμηση)");
    else if(state.mode==="car") h.textContent = (LANG==="en"?"To ":"Ως ") + destLabel() + (LANG==="en"?" by car, rush hour (estimate)":" με αυτοκίνητο, ώρα αιχμής (εκτίμηση)");
    else h.textContent = T(h.textContent);
    document.querySelectorAll("#legend b").forEach(b=>b.textContent=T(b.textContent));
    document.querySelectorAll("#legend small").forEach(s=>s.textContent=T(s.textContent));
  };
  const _cmpRows = cmpRows;
  cmpRows = a => {
    const sc=scoreOf(a), rows=_cmpRows(a).map(r=>{ const r2=[...r]; r2[0] = r[0]==="Με ΜΜΜ ως το κέντρο" ? (LANG==="en"?"Public transport to ":"Με ΜΜΜ ως ")+destLabel() : T(r[0]); return r2; });
    return [[T("Βαθμολογία")+" (0–100)", sc?Math.round(sc.s):"—", sc?sc.s:null, "high"], ...rows];
  };
  const _exportRows = exportRows;
  exportRows = list => _exportRows(list).map((r,i)=>{ const sc=scoreOf(list[i]); return {...r, "βαθμολογία_0_100": sc?Math.round(sc.s):""}; });
  renderData = function(){
    document.getElementById("dtab").innerHTML = datasetRows(allAreas()).map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td class="n">${r[2]}</td><td>${r[3]}</td><td class="n">${DATASET_DATE[r[0]]||"—"}</td></tr>`).join("");
  };
  const _paint = paint;
  paint = function(){
    SC = null; _paint();
    const mob = matchMedia("(max-width:700px)").matches;
    document.body.classList.toggle("sheet-open", mob && state.sel!=null);
  };
  const _updateCityUI = updateCityUI;
  updateCityUI = function(){
    _updateCityUI();
    if(LANG==="en"){
      document.getElementById("h1").textContent = `Where (not) to live in ${T(C().name)}`;
      document.getElementById("intro").textContent = city==="athens"
        ? "Map of Athens areas with the categories from the Oneman article and the Spitogatos list, plus travel times, rents, crime and census data. Tap an area to see its details."
        : "Map of Thessaloniki municipalities with census population, rents and travel times. Tap an area to see its details.";
      ["all","mid","center"].forEach((v,j)=>document.getElementById("tab-"+v).textContent = T(C().tabs[j]));
    }
    updDestUI();
  };
}

// ----- Συνδέσεις κουμπιών -----
{
  const ms = ["cats","time","car","crime","rent","score"];
  setMode = function(m){ state.mode=m; state.filter=null; ms.forEach(n=>{ const b=document.getElementById("mode-"+n); if(b) b.setAttribute("aria-pressed", m===n); }); paint(); };
  ms.forEach(n=>{ const b=document.getElementById("mode-"+n); if(b) b.onclick=()=>setMode(n); });
  document.getElementById("score-go").onclick=()=>{ setMode("score"); document.querySelector(".mapbox").scrollIntoView({behavior:"smooth",block:"nearest"}); };
  document.getElementById("dest-sel").onchange=e=>{
    const v=e.target.value;
    if(v==="") setDest(null); else if(v!=="custom"){ const d=DESTS[city][+v]; setDest({name:d[0], lon:d[1], lat:d[2], city, gi: city==="athens" ? (+v)+1 : null}); }
  };
  document.getElementById("dest-pick").onclick=startPick;
  const ob=document.getElementById("tog-osm");
  ob.onclick=()=>{ osmOn = ob.getAttribute("aria-pressed")!=="true"; ob.setAttribute("aria-pressed",osmOn);
    if(osmOn){ L_osm.addTo(map); osmLoad(); } else { map.removeLayer(L_osm); osmMsg(""); } };
  document.getElementById("lang-btn").onclick=()=>{
    LANG = LANG==="en" ? "el" : "en"; try{ localStorage.setItem("lang",LANG); }catch(e){}
    applyStaticLang(); relabel(); renderWeights(); updateCityUI(); paint(); muniLabels();
  };
  addEventListener("resize", ()=>document.body.classList.toggle("sheet-open", matchMedia("(max-width:700px)").matches && state.sel!=null));
}

// ----- Ονόματα και περιγράμματα δήμων (Θεσσαλονίκη) -----
const L_mout = L.layerGroup().addTo(map), L_mlbl = L.layerGroup().addTo(map);
if(window.MUNI_OUT){
  L.geoJSON(MUNI_OUT, {interactive:false, style:{fill:false, color:tok("ink"), weight:2.2, opacity:.55}}).addTo(L_mout);
  MUNI_OUT.features.forEach(f=>{
    const p=f.properties;
    p.m = L.marker([p.lp[1],p.lp[0]], {interactive:false, keyboard:false, icon:L.divIcon({className:"munilbl", html:`<span>${p.n}</span>`, iconSize:null})});
  });
}
function muniLabels(){
  if(!window.MUNI_OUT) return;
  const z=map.getZoom();
  MUNI_OUT.features.forEach(f=>{ const p=f.properties, show = z>=11.5 && z<15;
    p.m.setIcon(L.divIcon({className:"munilbl", html:`<span>${LANG==="en" ? "Municipality of "+translit(p.n.replace(/^Δήμος /,"")) : p.n}</span>`, iconSize:null}));
    if(show) p.m.addTo(L_mlbl); else L_mlbl.removeLayer(p.m); });
}
map.on("zoomend", muniLabels);

// ----- Κατάταξη από τα στοιχεία για περιοχές που δεν αναφέρει καμία πηγή -----
function baseTime(a){ return gtfsOf(a) ?? TIME_UNIT[a.name] ?? TIME_MUNI[a.mid] ?? null; }
function derivedCat(a){
  const t=baseTime(a), r=rentOf(a), cr=crimeRate(a), own = cr && !cr.avg && !cr.nomos && !cr.scope, lim = a.city==="thess" ? 10 : 14;
  const ctr = a.city==="thess" ? "την Πλ. Αριστοτέλους" : "το Σύνταγμα";
  if(t!=null && t>=60) return ["far", `χρόνος με ΜΜΜ ~${Math.round(t)}′ ως ${ctr} (60′ ή περισσότερο)`];
  if(r && r[0]>=lim) return ["pricey", `μέσο ζητούμενο ενοίκιο ${nf.format(r[0])} €/m² (${lim} €/m² ή περισσότερο)`];
  if(own && cr.r>=11) return ["avoid", `${nf.format(Math.round(cr.r*10)/10)} κλοπές-διαρρήξεις ανά 1.000 κατοίκους (11 ή περισσότερες)`];
  return ["ok", `χρόνος ~${t!=null?Math.round(t):"—"}′ ως ${ctr}, ${r?`ενοίκιο ${nf.format(r[0])} €/m²`:"χωρίς στοιχείο ενοικίου"}, ${own?`${nf.format(Math.round(cr.r*10)/10)} κλοπές-διαρρήξεις ανά 1.000`:"χωρίς δικό της στοιχείο εγκληματικότητας"}· κανένα όριο για «Μακριά» (60′), «Απλησίαστη» (${lim} €/m²) ή «Αποφυγή» (11 ανά 1.000)`];
}
const isDerived = a => !custom[a.name] && a.cat==="none";
catOf = a => custom[a.name] || (a.cat!=="none" ? a.cat : derivedCat(a)[0]);
{
  const _sf = styleFor;
  styleFor = function(a,i,fa){ const st=_sf(a,i,fa); if(state.mode==="cats" && isDerived(a) && state.sel!==i){ st.fillOpacity=Math.min(st.fillOpacity,.3); st.dashArray="4 4"; } return st; };
  const _lg = legend;
  legend = function(){ _lg();
    if(state.mode!=="cats") return;
    const n=areas.filter(a=>a.city===city && isDerived(a)).length; if(!n) return;
    const li=document.createElement("li"); li.className="cnote";
    li.textContent=`${n} περιοχές δεν τις αναφέρει καμία πηγή και κατατάσσονται από τα στοιχεία (αχνό χρώμα, διακεκομμένο περίγραμμα): «Μακριά» αν θέλουν 60′ ή περισσότερο με ΜΜΜ, «Απλησίαστη» αν το ενοίκιο είναι ${city==="thess"?10:14} €/m² ή περισσότερο, «Αποφυγή» αν έχουν 11 ή περισσότερες κλοπές-διαρρήξεις ανά 1.000, αλλιώς «Οκ».`;
    document.getElementById("legend").appendChild(li);
  };
}

buildAll(); renderWeights(); applyStaticLang(); if(LANG==="en") relabel(); updateCityUI(); paint(); muniLabels();
